ROOT=Path(__file__).resolve().parents[3];OUT=Path(sys.argv[1]).resolve();sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'));assert not (OUT/'payload-manifest.json').exists()
